content.text:
{
  "devices": [
    {
      "device": "bio_shake",
      "existing_tags": [
        {
          "id": "4312",
          "name": "备料&前处理设备",
          "name_en": "Material Preparation & Pre-processing Equipment",
          "rationale": "用于PCR板/微孔板样品在恒温条件下的混匀与预处理，典型前处理步骤。"
        },
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "rationale": "可设定温度与振荡曲线执行孵育/反应混匀，直接参与实验过程。"
        },
        {
          "id": "4319",
          "name": "溶液配制与反应",
          "name_en": "Solution Preparation & Reaction",
          "rationale": "在溶液体系中进行控温振荡与孵育，促进反应/均质化。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "rationale": "用于分子生物学与酶标反应等生命科学场景的板级孵育混匀。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "rationale": "适用于细胞相关的板级孵育/培养流程中的温控振荡。"
        },
        {
          "id": "4334",
          "name": "移液站产品",
          "name_en": "Liquid Handling Station Products",
          "rationale": "装置支持与实验室自动化集成，常与移液工作站联用进行高通量流程。"
        },
        {
          "id": "4421",
          "name": "热混匀仪",
          "name_en": "Thermomixer",
          "rationale": "设备即为微孔板热混匀平台，具备加热/冷却与振荡功能。"
        }
      ],
      "proposed_new_tags": []
    },
    {
      "device": "cc_core",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "rationale": "作为序列与定时控制核心，负责触发与执行量子实验流程。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0001",
          "name": "量子实验控制",
          "name_en": "Quantum Experiment Control",
          "rationale": "面向量子实验的时序/序列控制、DIO链路校准与触发管理，属于量子控制领域。"
        },
        {
          "id": "P-0002",
          "name": "超导量子比特实验",
          "name_en": "Superconducting Qubit Experiments",
          "rationale": "描述明确服务的应用场景：超导量子比特的编程、触发与时序协同控制。"
        },
        {
          "id": "P-0003",
          "name": "量子序列控制器",
          "name_en": "Quantum Sequencer Controller",
          "rationale": "硬件序列器/定时控制器设备类型，与CC、CCIO、VSM联动完成量子序列执行。"
        }
      ]
    },
    {
      "device": "cryo_tel_gt",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "rationale": "在实验过程中提供低温设定点与功率模式控制，支撑实验执行。"
        },
        {
          "id": "4316",
          "name": "表征设备",
          "name_en": "Characterization Equipment",
          "rationale": "用于低温条件下的测试/表征（如探测器与样品性能测量）的温控支撑。"
        },
        {
          "id": "4350",
          "name": "稀土永磁与超导材料",
          "name_en": "Rare Earth Permanent Magnet & Superconducting Materials",
          "rationale": "常用于超导器件/材料的低温运行与稳定，契合该场景需求。"
        }
      ],
      "proposed_new_tags": [
        {
          "id": "P-0004",
          "name": "低温物理与低温工程",
          "name_en": "Cryogenic Physics & Engineering",
          "rationale": "设备核心用途为低温制冷与稳定控制，直接对应低温工程/物理领域。"
        },
        {
          "id": "P-0005",
          "name": "低温制冷机（斯特林冷头）",
          "name_en": "Cryocooler (Stirling Cold Head)",
          "rationale": "设备类型为斯特林式低温制冷机，带集成控制器与串口通信。"
        }
      ]
    },
    {
      "device": "cvd_control",
      "existing_tags": [
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "rationale": "按配方控制气体流量与温度在基底上沉积薄膜，执行合成过程。"
        },
        {
          "id": "4322",
          "name": "表面/薄膜体系",
          "name_en": "Surface / Thin Film System",
          "rationale": "CVD工艺用于薄膜沉积与表面工程，直接属于薄膜体系。"
        },
        {
          "id": "4326",
          "name": "化工放大与连续工艺优化",
          "name_en": "Chemical Scale-up & Continuous Process Optimization",
          "rationale": "具备配方管理与过程监控，支持工艺稳定性与可重复性优化。"
        },
        {
          "id": "4344",
          "name": "涂层材料",
          "name_en": "Coating Materials",
          "rationale": "CVD常用于制备功能涂层与保护层，符合该应用场景。"
        },
        {
          "id": "4349",
          "name": "二维材料",
          "name_en": "2D Materials",
          "rationale": "CVD广泛用于石墨烯/二维材料的薄膜生长，适配此场景。"
        },
        {
          "id": "4373",
          "name": "化学气相沉积设备",
          "name_en": "Chemical Vapor Deposition System",
          "rationale": "设备即为CVD薄膜沉积系统，含反应腔体、加热与质量流量控制。"
        }
      ],
      "proposed_new_tags": []
    },
    {
      "device": "cytomat_backend",
      "existing_tags": [
        {
          "id": "4315",
          "name": "器件/细胞设备",
          "name_en": "Device / Cell Equipment",
          "rationale": "面向细胞/微生物的板级培养与存储，属于细胞设备范畴。"
        },
        {
          "id": "4313",
          "name": "实验执行&合成设备",
          "name_en": "Experiment Execution & Synthesis Equipment",
          "rationale": "执行恒温、气体与湿度控制并自动搬运微板，是培养流程的执行单元。"
        },
        {
          "id": "4318",
          "name": "生命体系",
          "name_en": "Life Sciences",
          "rationale": "用于细胞培养与微生物培养等生命科学场景。"
        },
        {
          "id": "4330",
          "name": "细胞生物学研究",
          "name_en": "Cell Biology Research",
          "rationale": "支持CO2/O2控制与板级孵育，契合细胞生物学培养需求。"
        },
        {
          "id": "4334",
          "name": "移液站产品",
          "name_en": "Liquid Handling Station Products",
          "rationale": "带对接传送口与条码读取，常集成于自动化移液/筛选系统。"
        },
        {
          "id": "4387",
          "name": "微生物培养箱",
          "name_en": "Microbial Incubator",
          "rationale": "具备温度与气体环境控制的板级培养功能，符合培养箱属性。"
        },
        {
          "id": "4442",
          "name": "组织培养试验箱",
          "name_en": "Tissue Culture Chamber",
          "rationale": "提供CO2/O2/湿度控制的细胞培养环境，匹配组织/细胞培养需求。"
        },
        {
          "id": "4446",
          "name": "自动化耗材堆栈",
          "name_en": "Automated Consumable Stack",
          "rationale": "内置存储位与自动搬运微板，具备自动化耗材堆栈特征。"
        }
      ],
      "proposed_new_tags": []
    }
  ]
}

